def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    score = np.exp(-np.square(remaining))
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_residual = 0.5
    score = np.exp(-((remaining - optimal_residual) ** 2) / 0.2)
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_residual = 0.5
    score = 1.0 / (1.0 + np.abs(remaining - optimal_residual))
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    ratio = item / np.maximum(bins, 1e-9)
    return np.where(remaining < 0, -np.inf, ratio + (remaining / np.maximum(bins, 1e-9)))
